{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a small patch of ground with pebbles and sparse grass. It has the overall body, head, and limbs of a brown bear covered in dense, shaggy brown fur that is lighter tan on the muzzle, chest and flank, and darker on the legs. From the center of its forehead projects a single long, glossy, dark reddish-brown to black segmented horn that curves upward and backward. Covering its entire back from just behind the shoulders to above the hindquarters is a large, domed, glossy exoskeleton-like shell that is dark reddish-brown with black shading, appearing smooth and reflective.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head covered in shaggy brown fur with a lighter tan muzzle, a large black nose at the tip, small brown eyes on the side of the face, and a closed mouth with faint whiskers",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one long, glossy, segmented horn, dark brown to black with transverse ridges, tapering to a pointed tip and curving backward",
      "where": "arising from the midline of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry ears covered in brown fur",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, stout, columnar legs covered in long shaggy dark brown fur",
      "where": "two forelimbs under the chest and two hindlimbs under the rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with long, dark, curved claws visible at the tips",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very small, short, rounded furry protrusion",
      "where": "at the posterior end of the body above the hind legs, on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "a large, domed, glossy exoskeleton, dark reddish-brown to black, smooth and reflective with a pitted lower margin and two small pointed projections on the shoulder portion",
      "where": "covering the entire dorsal side from just behind the neck to above the tail"
    },
    {
      "part": "plates",
      "looks_like": "transverse segmented plates forming the shell, with about seven to eight major dorsal segments separated by dark lines, and a lower lateral row of smaller overlapping plates each with an oval hole, plus a larger smooth shoulder plate",
      "where": "composing the shell on the back, with the major segments on top and the smaller holed plates along the lower edge"
    },
    {
      "part": "markings",
      "looks_like": "lighter tan to cream fur contrasting with the darker brown, forming a patch on the side of the torso and chest and a lighter muzzle",
      "where": "on the lateral chest and mid-flank and on the face around the nose and mouth"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
